import json, re, zlib, base64, collections
cap=json.load(open("/tmp/capture.json"))
# key helpers
def key_of(path): return " ".join(path)
paths=[]
# reconstruct from capture keys
for k in cap.keys():
    if k.endswith("::--help"):
        p=k[:-len("::--help")]
        path=p.split("|") if p else []
        paths.append(path)
# sort?
help_dict={}
json_dict={}
for path in paths:
    k="|".join(path)
    help_dict[key_of(path)]=cap[k+"::--help"][1]
    if k+"::--json-usage" in cap:
        json_dict[key_of(path)]=cap[k+"::--json-usage"][1]
# root special keys are ""? capture uses ::--help for root? Check earlier: keys like "::--help" path []
# in cap, root help key is "::--help" -> p="" -> path=[]
# good

# groups: nodes with sub_algorithms in json
groups={}
aliases_map={} # parent key -> {alias: canonical}
children={} # parent key -> list canonical names
for path in paths:
    k="|".join(path)
    if k+"::--json-usage" not in cap: continue
    try: d=json.loads(cap[k+"::--json-usage"][1])
    except: continue
    subs=d.get("sub_algorithms",[])
    if subs:
        lst=[]
        for s in subs:
            name=s["name"]; lst.append(name)
        children[key_of(path)]=lst
# root add convert/info
children[""]=["convert","dataset","driver","info","mdim","pipeline","raster","vector","vsi"]
# parse group help for aliases
for parent, childs in list(children.items()):
    # help text lines in where section
    txt=help_dict.get(parent,"")
    am={}
    for line in txt.splitlines():
        m=re.match(r"\s+-\s+([^:\s]+):.*\(alias:\s*([^)]+)\)", line)
        if m:
            canon=m.group(1)
            for a in [x.strip() for x in m.group(2).split(",")]:
                am[a]=canon
    if am:
        aliases_map[parent]=am
# Also driver cog etc children from json already

# parse args for leaf nodes
def parse_entries(txt):
    entries=[] # (section, aliases, label, line)
    sec=None
    for line in txt.splitlines():
        if line.startswith("For more details") or line.startswith("WARNING"):
            sec=None
        if re.match(r"^[^ ].*:$", line) or line=="Positional arguments:":
            sec=line; continue
        if sec and line.startswith("  ") and not line.startswith("   ") and line.strip():
            s=line.strip()
            m=re.match(r"^(.*?)\s{2,}\S", s)
            left=m.group(1) if m else s
            parts=[p.strip() for p in left.split(",")]
            aliases=[]
            label=None
            for p in parts:
                if not p: continue
                tok=p.split()[0]
                if tok.startswith("-"):
                    aliases.append(tok)
                    # label is remainder of this part after alias if any
                    rest=p[len(tok):].strip()
                    if rest and label is None:
                        label=rest
                else:
                    if label is None and tok.startswith("<"):
                        label=tok
            entries.append((sec,aliases,label,left))
    return entries

args_dict={}
usage_dict={}
leafname={}
for path in paths:
    k="|".join(path)
    if k+"::--json-usage" not in cap: continue
    try: d=json.loads(cap[k+"::--json-usage"][1])
    except: continue
    if d.get("sub_algorithms"): continue
    # pipeline etc still include
    txt=help_dict.get(key_of(path),"")
    if txt:
        first=txt.splitlines()[0] if txt else ""
        usage_dict[key_of(path)]=first[len("Usage: "):] if first.startswith("Usage: ") else first
    entries=parse_entries(txt)
    # map canonical name -> entry
    # build entry lookup by alias --
    entry_by_long={}
    for sec,aliases,label,left in entries:
        for a in aliases:
            if a.startswith("--"):
                entry_by_long[a[2:]]=(sec,aliases,label)
    args=[]
    seen=set()
    for cat in ["input_arguments","output_arguments","input_output_arguments"]:
        for a in d.get(cat,[]):
            name=a["name"]
            if name in ("output-string","return-code"): continue
            if name in seen: continue
            seen.add(name)
            ent=entry_by_long.get(name)
            if not ent:
                # try if arg is pipeline or ??? pipeline node special
                if name=="pipeline":
                    args.append({"name":name,"type":a["type"],"required":a.get("required",False),"aliases":["--pipeline"],"positional":False,"label":"PIPELINE"})
                    continue
                # hidden? skip
                continue
            sec,aliases,label=ent
            na=dict()
            for f in ["name","type","required","default","choices","min_value","min_value_is_included","max_value","max_value_is_included","packed_values_allowed","repeated_arg_allowed","min_count","max_count","metavar","mutual_exclusion_group","dataset_type"]:
                if f in a: na[f]=a[f]
            na["aliases"]=aliases
            na["positional"]=(sec=="Positional arguments:")
            na["label"]=label
            args.append(na)
    args_dict[key_of(path)]=args
    leafname[key_of(path)]= path[-1] if path else "gdal"

# Bare/group error usage template: derive from captured bare stderr
bare_template={}
for path in paths:
    k="|".join(path)
    if k+"::__bare__" in cap:
        rc,out,err=cap[k+"::__bare__"]
        bare_template[key_of(path)]=err
# root bare
if "::__bare__" in cap:
    bare_template[""]=cap["::__bare__"][2]

# drivers outputs
drivers={}
for mode_key, capkey in [("","--drivers"),("raster","raster|--drivers"),("vector","vector|--drivers"),("mdim","mdim|--drivers")]:
    pass
# capture file keys for drivers we saved: look
print("capture keys sample drivers", [k for k in cap if "drivers" in k])

spec={
 "help":help_dict,
 "json":json_dict,
 "children":children,
 "aliases":aliases_map,
 "args":args_dict,
 "usage":usage_dict,
 "leafname":leafname,
 "bare":bare_template,
}
blob=zlib.compress(json.dumps(spec, separators=(",",":")).encode(),9)
b85=base64.b85encode(blob).decode()
with open("spec_data.py","w") as f:
    f.write("import zlib, base64, json\n_B=r'"+b85+"'\nSPEC=json.loads(zlib.decompress(base64.b85decode(_B.encode())))\n")
print("spec paths",len(help_dict), "blob",len(blob), "b85",len(b85))
print("children",children)
print("aliases",aliases_map)
# check some args
for p in ["raster info","raster create","vector info","dataset identify","raster calc","pipeline","convert","info"]:
    print(p, args_dict.get(p))
