    if isinstance(obj, str): return json_escape(obj)
    if isinstance(obj, int): return str(obj)
    if isinstance(obj, float):
        if math.isnan(obj): return "null"
        if math.isinf(obj): return "null"
        # python repr gives shortest
        r=repr(obj)
        return r
    if isinstance(obj, dict):
        if not obj:
            return "{\n"+sp+"}"
        items=[]
        for k,v in obj.items():
            items.append(sp2+json_escape(str(k))+":"+gdal_json_dumps(v, indent+1))
        return "{\n"+",\n".join(items)+"\n"+sp+"}"
    if isinstance(obj, (list,tuple)):
        if not obj:
            return "[\n"+sp+"]"
        items=[sp2+gdal_json_dumps(v, indent+1) for v in obj]
