def resolve_vrt_path(base_dir, fn, relative):
    if relative and base_dir:
        p=os.path.join(base_dir, fn)
        return os.path.normpath(p)
    return fn

def read_vrt(path, display_name=None):
    tree=ET.parse(path); root=tree.getroot()
    if root.tag!="VRTDataset": raise ValueError("not VRT")
    w=int(root.get("rasterXSize")); h=int(root.get("rasterYSize"))
    base_dir=os.path.dirname(path)
    display_base=os.path.dirname(display_name) if display_name else base_dir
    metadata={}
    for md in root.findall("Metadata"):
        domain=md.get("domain","")
        d={}
        for mdi in md.findall("MDI"): d[mdi.get("key")]=mdi.text or ""
        metadata[domain]=d
    gt=None; has_gt=False
    gt_el=root.find("GeoTransform")
    if gt_el is not None and gt_el.text:
        vals=[float(x.strip()) for x in gt_el.text.split(",") if x.strip()!='']
        if len(vals)==6: gt=tuple(vals); has_gt=True
    crs=None
    srs_el=root.find("SRS")
    if srs_el is not None and srs_el.text and srs_el.text.strip():
        try: crs=parse_crs_string(srs_el.text.strip())
        except Exception:
            crs=CRS(name="unknown",wkt=srs_el.text.strip())
    # GCPs skip
    bands=[]
    files_extra=[display_name or path]
    for band_el in root.findall("VRTRasterBand"):
        dtype=band_el.get("dataType","Byte"); bidx=int(band_el.get("band","1"))
        band=Band(dtype=dtype,w=w,h=h,color_interp="Undefined")
        # init nodata 0
        band.data=[cast_value(0,dtype)]*(w*h)
        ci=band_el.find("ColorInterp")
        if ci is not None and ci.text: band.color_interp=ci.text.strip()
        nd=band_el.find("NoDataValue")
        if nd is not None and nd.text: 
            try: band.nodata=float(nd.text)
            except: pass
        desc=band_el.find("Description")
        if desc is not None and desc.text: band.description=desc.text
        # metadata
        for md in band_el.findall("Metadata"):
            domain=md.get("domain","")
            # band metadata generally domain "" stored as band metadata if no domain or ??? GDAL band metadata default
            for mdi in md.findall("MDI"):
                if domain in ("",None): band.metadata[mdi.get("key")]=mdi.text or ""
                # else ignore?
        scale_el=band_el.find("Scale"); off_el=band_el.find("Offset")
        # In VRT Scale/Offset are elements? Actually child <Scale>?? Search
        for child in band_el:
            if child.tag=="Scale" and child.text: band.scale=float(child.text)
            if child.tag=="Offset" and child.text: band.offset=float(child.text)
