        for src in band_el:
            if src.tag not in ("SimpleSource","ComplexSource","AveragedSource","MultiSource"): continue
            fn_el=src.find("SourceFilename"); sb_el=src.find("SourceBand")
            if fn_el is None: continue
            src_fn=fn_el.text or ""; rel=fn_el.get("relativeToVRT","0")=="1"
            src_path=resolve_vrt_path(base_dir, src_fn, rel)
            # display files extra uses ? Original VRT info files: a.tif as relative as written? For a.vrt created, files were a.vrt, a.tif (relative name as in SourceFilename if relative? but path resolution for listing: they listed a.tif (as relative string) not absolute)
            display_src=src_fn if rel else src_path
            # If display_name is relative and source is relative, keep as written
            if display_src not in files_extra: files_extra.append(display_src)
            try:
                src_raster=open_raster(src_path, display_name=src_path)
            except Exception:
                continue
            sb=int(sb_el.text) if sb_el is not None and sb_el.text else 1
            if sb<1 or sb>len(src_raster.bands): continue
            src_band=src_raster.bands[sb-1]
            src_rect=src.find("SrcRect"); dst_rect=src.find("DstRect")
            sx=sy=0; sw=src_raster.w; sh=src_raster.h; dx=dy=0; dw=w; dh=h
            if src_rect is not None:
                sx=float(src_rect.get("xOff",0)); sy=float(src_rect.get("yOff",0)); sw=float(src_rect.get("xSize",sw)); sh=float(src_rect.get("ySize",sh))
            if dst_rect is not None:
                dx=float(dst_rect.get("xOff",0)); dy=float(dst_rect.get("yOff",0)); dw=float(dst_rect.get("xSize",dw)); dh=float(dst_rect.get("ySize",dh))
            # scale ratio/offset for ComplexSource
            scale_ratio=1.0; scale_offset=0.0
            sr=src.find("ScaleRatio"); so=src.find("ScaleOffset")
            if sr is not None and sr.text: scale_ratio=float(sr.text)
            if so is not None and so.text: scale_offset=float(so.text)
            # Also SourceProperties nodata?
            # Fill dst rect with resampled (?) nearest from src rect
            for yy in range(int(dy), int(dy+dh)):
                if yy<0 or yy>=h: continue
                src_y=int(sy + (yy-dy)*(sh/dh)) if dh else int(sy)
                if src_y<0 or src_y>=src_raster.h: continue
                for xx in range(int(dx), int(dx+dw)):
                    if xx<0 or xx>=w: continue
                    src_x=int(sx + (xx-dx)*(sw/dw)) if dw else int(sx)
                    if src_x<0 or src_x>=src_raster.w: continue
                    v=src_band.data[src_y*src_raster.w+src_x]
                    if src.tag=="ComplexSource":
