    shx_header=bytearray(100); struct.pack_into('>i', shx_header,0,9994); struct.pack_into('>i', shx_header,24,(100+len(shp_records)*8)//2); struct.pack_into('<i', shx_header,28,1000); struct.pack_into('<i', shx_header,32,shape_type); struct.pack_into('<d', shx_header,36,xmin); struct.pack_into('<d', shx_header,44,ymin); struct.pack_into('<d', shx_header,52,xmax); struct.pack_into('<d', shx_header,60,ymax)
    shx_data=bytearray(shx_header)
    for off,ln in shx_offsets: shx_data.extend(struct.pack('>ii', off, ln))
    dname=os.path.dirname(os.path.abspath(base+".shp")); os.makedirs(dname, exist_ok=True)
    with open(base+".shp","wb") as f: f.write(shp_data)
    with open(base+".shx","wb") as f: f.write(shx_data)
    # DBF
    # Fields trunc to 10 chars (shapefile limitation) - GDAL truncates and warns? We'll keep mapping orig->dbf name
    dbf_fields=[]
    for field in layer.fields:
        name=field.name[:10]
        # Types: String C width 80? Integer N width? Real etc
        if field.type in ("Integer",): typ='N'; width=10; dec=0
        elif field.type=="Integer64": typ='N'; width=20; dec=0
        elif field.type=="Real": typ='N'; width=24; dec=15 # GDAL default? probe later
        elif field.type=="Date": typ='D'; width=8; dec=0
        else: typ='C'; width=field.width if field.width else 80; dec=0
        dbf_fields.append((name,typ,width,dec,field))
    header_len=32+len(dbf_fields)*32+1
    record_len=1+sum(w for _,_,w,_,_ in dbf_fields)
    dbf=bytearray()
    now=datetime.date.today()
    dbf.extend(bytes([0x03, now.year-1900, now.month, now.day]))
    dbf.extend(struct.pack('<IHHH', len(layer.features), header_len, record_len))
    dbf.extend(b'\x00'*20)
    for name,typ,width,dec,field in dbf_fields:
        name_b=name.encode()[:10].ljust(11,b'\x00')
        dbf.extend(name_b); dbf.extend(typ.encode()); dbf.extend(b'\x00'*4); dbf.extend(bytes([width,dec])); dbf.extend(b'\x00'*14)
    dbf.extend(b'\r')
    for f in layer.features:
        rec=bytearray(b' ')
        for name,typ,width,dec,field in dbf_fields:
            v=f.properties.get(field.name)
            if v is None: s=""
            elif typ=='N':
                if dec>0: s=f"{float(v):{width}.{dec}f}"[-width:]
                else: s=f"{int(v)}".rjust(width)[-width:]
            elif typ=='D': s=str(v).replace("-","")[:8].ljust(8)
            else: s=str(v)[:width]
            if typ=='N': rec.extend(s.encode().rjust(width)[-width:])
            else: rec.extend(s.encode().ljust(width)[:width])
        dbf.extend(rec)
    dbf.extend(b'\x1a')
    with open(base+".dbf","wb") as out: out.write(dbf)
    # prj
    if layer.crs and layer.crs.epsg:
        # ESRI WKT1 approx - for reading back by our reader we can store a special? Our reader will parse prj to epsg by detecting name.
        prj_text=esri_wkt_for_epsg(layer.crs.epsg, layer.crs.name)
        with open(base+".prj","w") as out: out.write(prj_text)
    # cpg
    with open(base+".cpg","w") as out: out.write("UTF-8")
    return base+".shp"

def esri_wkt_for_epsg(code, name=None):
    if code==4326:
        return 'GEOGCS["WGS 84",DATUM["WGS_1984",SPHEROID["WGS 84",6378137,298.257223563]],PRIMEM["Greenwich",0],UNIT["Degree",0.0174532925199433]]'
    if code==3857:
        return 'PROJCS["WGS 84 / Pseudo-Mercator",GEOGCS["WGS 84",DATUM["WGS_1984",SPHEROID["WGS 84",6378137,298.257223563]],PRIMEM["Greenwich",0],UNIT["Degree",0.0174532925199433]],PROJECTION["Mercator_1SP"],PARAMETER["central_meridian",0],PARAMETER["scale_factor",1],PARAMETER["false_easting",0],PARAMETER["false_northing",0],UNIT["Meter",1]]'
    # Generic store EPSG code in name for our reader recovery (GDAL would produce full but unknown)
    # Use a WKT that includes AUTHORITY
    if 32601 <= code <= 32660 or 32701 <= code <= 32760:
        zone=code%100; hemi="Northern" if code<32700 else "Southern"
        return f'PROJCS["WGS 84 / UTM zone {zone}{"N" if code<32700 else "S"}",GEOGCS["WGS 84",DATUM["WGS_1984",SPHEROID["WGS 84",6378137,298.257223563]],PRIMEM["Greenwich",0],UNIT["Degree",0.0174532925199433]],PROJECTION["Transverse_Mercator"],PARAMETER["latitude_of_origin",0],PARAMETER["central_meridian",{-183+6*zone}],PARAMETER["scale_factor",0.9996],PARAMETER["false_easting",500000],PARAMETER["false_northing",{0 if code<32700 else 10000000}],UNIT["Meter",1],AUTHORITY["EPSG","{code}"]]'
    return f'PROJCS["{name or code}",GEOGCS["WGS 84",DATUM["WGS_1984",SPHEROID["WGS 84",6378137,298.257223563]],PRIMEM["Greenwich",0],UNIT["Degree",0.0174532925199433]],UNIT["Meter",1],AUTHORITY["EPSG","{code}"]]'

def geom_to_shape(geom, shape_type, layer_geom_type):
    if geom is None:
        return struct.pack('<i',0), None
    t=geom.get("type")
    coords=geom_coords(geom)
    if coords:
        bbox=(min(x for x,y in coords), min(y for x,y in coords), max(x for x,y in coords), max(y for x,y in coords))
    else: bbox=None
    # Null if type mismatch? For simplicity encode based on geom type
    if t=="Point":
        c=geom["coordinates"]; return struct.pack('<idd',1,float(c[0]),float(c[1])), bbox
    if t=="MultiPoint":
        pts=geom["coordinates"]; out=struct.pack('<idddd i',8, bbox[0],bbox[1],bbox[2],bbox[3], len(pts)) if bbox else struct.pack('<i',0)
        # struct formatting above incorrect with space, rebuild
        out=struct.pack('<i',8)+struct.pack('<dddd',*bbox)+struct.pack('<i',len(pts))
        for p in pts: out+=struct.pack('<dd',float(p[0]),float(p[1]))
        return out, bbox
    if t=="LineString":
        pts=geom["coordinates"]; out=struct.pack('<i',3)+struct.pack('<dddd',*bbox)+struct.pack('<ii',1,len(pts))+struct.pack('<i',0)
        for p in pts: out+=struct.pack('<dd',float(p[0]),float(p[1]))
        return out, bbox
    if t=="MultiLineString":
        lines=geom["coordinates"]; total=sum(len(l) for l in lines); parts=[]; offset=0
        for l in lines: parts.append(offset); offset+=len(l)
        out=struct.pack('<i',3)+struct.pack('<dddd',*bbox)+struct.pack('<ii',len(lines),total)
        for pidx in parts: out+=struct.pack('<i',pidx)
        for l in lines:
            for p in l: out+=struct.pack('<dd',float(p[0]),float(p[1]))
        return out, bbox
    if t=="Polygon":
        rings=geom["coordinates"]; total=sum(len(r) for r in rings); parts=[]; offset=0
        for r in rings: parts.append(offset); offset+=len(r)
        out=struct.pack('<i',5)+struct.pack('<dddd',*bbox)+struct.pack('<ii',len(rings),total)
        for pidx in parts: out+=struct.pack('<i',pidx)
        for r in rings:
            for p in r: out+=struct.pack('<dd',float(p[0]),float(p[1]))
        return out, bbox
    if t=="MultiPolygon":
        polys=geom["coordinates"]; total_rings=sum(len(poly) for poly in polys); total_pts=sum(len(r) for poly in polys for r in poly); parts=[]; offset=0
        for poly in polys:
            for r in poly: parts.append(offset); offset+=len(r)
        out=struct.pack('<i',5)+struct.pack('<dddd',*bbox)+struct.pack('<ii',total_rings,total_pts)
        for pidx in parts: out+=struct.pack('<i',pidx)
        for poly in polys:
            for r in poly:
                for p in r: out+=struct.pack('<dd',float(p[0]),float(p[1]))
        return out, bbox
    return struct.pack('<i',0), bbox

def read_shapefile(path, display_name=None):
    # path may be .shp, .dbf, .shz, directory, zip?
    base=path
    if base.lower().endswith((".shp",".dbf",".shx",".prj")): base=base[:-4]
    shp_path=base+".shp"; dbf_path=base+".dbf"
    # read dbf fields
    fields=[]; records_props=[]
    dbf_field_defs=[]
    if os.path.exists(dbf_path):
        data=open(dbf_path,"rb").read()
        nrec=struct.unpack('<I', data[4:8])[0]; header_len=struct.unpack('<H', data[8:10])[0]; rec_len=struct.unpack('<H', data[10:12])[0]
        for off in range(32, header_len-1, 32):
            name=data[off:off+11].split(b'\x00')[0].decode('utf-8',errors='ignore')
            typ=chr(data[off+11]); width=data[off+16]; dec=data[off+17]
            dbf_field_defs.append((name,typ,width,dec))
            # map types
            if typ=='C': ftype="String"
            elif typ=='N': ftype="Real" if dec>0 else "Integer"
            elif typ=='D': ftype="Date"
            elif typ=='L': ftype="Integer"
            elif typ=='F': ftype="Real"
            else: ftype="String"
            fields.append(Field(name, ftype, width if typ=='C' else 0, dec))
        for i in range(nrec):
            off=header_len+i*rec_len
            rec=data[off:off+rec_len]
            if rec[:1]==b'*': 
                records_props.append(None); continue
            props={}; pos=1
            for (name,typ,width,dec), field in zip(dbf_field_defs, fields):
                raw=rec[pos:pos+width]; pos+=width
                s=raw.decode('utf-8',errors='ignore')
                if typ=='C': v=s.rstrip() if s.strip()!='' else None; # GDAL trims? Keeps ''? Shapefile null strings become None? We'll use stripped or None if blank? Original OGR: empty string fields become None?
                elif typ=='N':
                    st=s.strip()
                    if st=='': v=None
                    else: v=float(st) if dec>0 or '.' in st else int(st)
                elif typ=='D':
                    st=s.strip(); v=f"{st[:4]}-{st[4:6]}-{st[6:8]}" if len(st)==8 and st!='' else None
                elif typ=='L': v=1 if s in ('T','t','Y','y') else 0 if s in ('F','f','N','n') else None
                else: v=s
                    # adjust v defined
                if typ=='C': 
                    # empty becomes None in OGR for shapefile (?) keep None if blank
                    if s.strip()=='': v=None
                props[field.name]=v
            records_props.append(props)
    # read shp
    geometries=[]
    shape_type=0
    if os.path.exists(shp_path):
        data=open(shp_path,"rb").read()
        if len(data)>=100:
            shape_type=struct.unpack('<i', data[32:36])[0]
            off=100
            while off+8 <= len(data):
                rec_num, content_len=struct.unpack('>ii', data[off:off+8]); off+=8
                content=data[off:off+content_len*2]; off+=content_len*2
                geometries.append(shape_to_geom(content))
    features=[]
    max_rec=max(len(geometries), len(records_props))
    for i in range(max_rec):
        geom=geometries[i] if i < len(geometries) else None
        props=records_props[i] if i < len(records_props) else {}
        if props is None: continue # deleted
        features.append(Feature(i, props or {}, geom))
    # fid for shapefiles starts 0? OGR Shapefile FIDs are 0-based? In vector info --features, OGRFeature(...):0 for first shapefile feature typically. We'll set 0-based if no fid col.
    for i,f in enumerate(features): f.fid=i
    geom_type_map={0:"Unknown",1:"Point",3:"LineString",5:"Polygon",8:"MultiPoint",11:"Point Z",13:"LineString Z",15:"Polygon Z",18:"MultiPoint Z"}
    # If shape_type is LineString but some geometries are MultiLineString, GDAL promotes? shape_to_geom returns LineString if 1 part else Multi
    inferred=infer_geom_type(features)
    layer_geom=geom_type_map.get(shape_type,"Unknown")
    # If inferred is Multi version and layer type is single, GDAL often reports Multi if any multi? Use inferred if it differs by multi
    if inferred!="Unknown" and inferred!=layer_geom:
        # If shape type 3/5, geometries may be single or multi depending parts; OGR reports based on shape type alone (LineString/Polygon) even if 1 part? Wait ESRI shapes are always multi-part capable but GDAL maps type 3 to MultiLineString? Check original later. We'll keep layer_geom for now unless inferred is Point etc.
        # Actually OGR Shapefile driver reports wkbLineString for type 3, and features may be LineString or MultiLineString depending.
        pass
    layer_name=os.path.splitext(os.path.basename(path))[0]
    crs=None
    prj_path=base+".prj"
    if os.path.exists(prj_path):
        prj_text=open(prj_path).read()
        # parse authority
        m=re.search(r'AUTHORITY\["EPSG","?(\d+)"?\]', prj_text)
        if m: crs=crs_from_epsg(int(m.group(1)))
        elif "WGS 84" in prj_text and "PROJCS" not in prj_text: crs=crs_from_epsg(4326)
        elif "Pseudo-Mercator" in prj_text or "Mercator_1SP" in prj_text and "WGS 84" in prj_text: crs=crs_from_epsg(3857)
        else:
            # generic with prj name
            mn=re.search(r'(?:PROJCS|GEOGCS)\["([^"]+)"', prj_text)
            name=mn.group(1) if mn else "Unknown"
            crs=CRS(epsg=None,name=name,wkt=prj_text,text=[f'  - name: {name}'],axis=[1,2],kind="Projected" if "PROJCS" in prj_text else "Geographic 2D",raw=prj_text)
    layer=Layer(layer_name, layer_geom, fields, features, crs=crs)
    ds=VectorDataset([layer], display_name or path, "ESRI Shapefile","ESRI Shapefile")
    return ds

def shape_to_geom(content):
    if len(content)<4: return None
    st=struct.unpack('<i', content[:4])[0]
    if st==0: return None
    if st==1:
        x,y=struct.unpack('<dd', content[4:20]); return {"type":"Point","coordinates":[x,y]}
    if st in (3,5,8):
        if len(content)<48: return None
        # bbox 32 bytes after type, then numParts, numPoints
        if st==8:
            npts=struct.unpack('<i', content[36:40])[0]; off=40; pts=[]
            for i in range(npts): x,y=struct.unpack('<dd', content[off:off+16]); off+=16; pts.append([x,y])
            return {"type":"MultiPoint","coordinates":pts}
        num_parts, num_points=struct.unpack('<ii', content[36:44]); off=44; parts=[]
        for i in range(num_parts): parts.append(struct.unpack('<i', content[off:off+4])[0]); off+=4
        pts=[]
        for i in range(num_points): x,y=struct.unpack('<dd', content[off:off+16]); off+=16; pts.append([x,y])
        segments=[]
        for pi in range(num_parts):
            start=parts[pi]; end=parts[pi+1] if pi+1<num_parts else num_points
            segments.append(pts[start:end])
        if st==3:
            if len(segments)==1: return {"type":"LineString","coordinates":segments[0]}
            return {"type":"MultiLineString","coordinates":segments}
        if st==5:
            if len(segments)==1: return {"type":"Polygon","coordinates":segments}
            # MultiPolygon vs Polygon with holes ambiguous: ESRI orientation determines. Assume Polygon if rings nested? Simplified: if segments count >1 and they are separate? GDAL groups by orientation/ containment. We'll return Polygon for now if we guess holes (ring inside first). Use area orientation: outer clockwise, holes counter. Simplify: treat as Polygon with all rings (may be wrong for multipolygon disjoint)
            # Check disjoint: if second ring is inside first (point in poly) then hole; else multipolygon.
            # Implement point in poly test for first point of each ring
            def point_in_ring(pt, ring):
                x,y=pt; inside=False; j=len(ring)-1
                for i in range(len(ring)):
                    xi,yi=ring[i]; xj,yj=ring[j]
                    if ((yi>y)!=(yj>y)) and (x < (xj-xi)*(y-yi)/(yj-yi+1e-300)+xi): inside=not inside
                    j=i
                return inside
            polys=[[segments[0]]]
            for ring in segments[1:]:
                if point_in_ring(ring[0], polys[-1][0]): polys[-1].append(ring)
                else: polys.append([ring])
            if len(polys)==1: return {"type":"Polygon","coordinates":polys[0]}
            return {"type":"MultiPolygon","coordinates":polys}
    if st==11: # Point Z
        x,y,z,m=struct.unpack('<dddd', content[4:36]); return {"type":"Point","coordinates":[x,y,z]}
    # Z/M types 13,15,18, etc similar ignoring Z - extract XY by skipping
    if st in (13,15):
        # structure: type, bbox(4), numParts, numPoints, parts, points, zrange, zarray, mrange, marray - XY part same as above
        num_parts, num_points=struct.unpack('<ii', content[36:44]); off=44; parts=[]
        for i in range(num_parts): parts.append(struct.unpack('<i', content[off:off+4])[0]); off+=4
        pts=[]
        for i in range(num_points): x,y=struct.unpack('<dd', content[off:off+16]); off+=16; pts.append([x,y])
        segments=[] 
        for pi in range(num_parts):
            start=parts[pi]; end=parts[pi+1] if pi+1<num_parts else num_points
            segments.append(pts[start:end])
        if st==13:
            return {"type":"LineString","coordinates":segments[0]} if len(segments)==1 else {"type":"MultiLineString","coordinates":segments}
        else:
            return {"type":"Polygon","coordinates":segments}
    return None

def open_vector(path, display_name=None):
    display_name=display_name or path
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    if os.path.isdir(path):
        # directory could be shapefile? Or ?? Treat as ??? Look for .shp inside
        shp_files=glob.glob(os.path.join(path,"*.shp"))
        if shp_files:
            # multiple layers? Shapefile directory driver reads each shp as layer
            layers=[]
            for shp in sorted(shp_files):
                ds_tmp=read_shapefile(shp, shp)
                layers.extend(ds_tmp.layers)
            return VectorDataset(layers, display_name, "ESRI Shapefile","ESRI Shapefile")
        raise ValueError("not vector")
    ext=os.path.splitext(path)[1].lower()
    # content sniff
    try:
        with open(path,"rb") as f: head=f.read(1024)
    except: head=b""
    if ext in (".shp",".dbf",".shx",".shz"):
        return read_shapefile(path, display_name)
    if ext in (".geojsonl",".geojsons"):
        return read_geojsonseq(path, display_name)
    # zip shapefile .shp.zip - not implemented
    # JSON detection
    txt_head=head.lstrip()
    if txt_head.startswith(b'{') or txt_head.startswith(b'['):
        try:
            data=json.loads(open(path,encoding="utf-8").read())
        except Exception:
            # GeoJSONSeq lines
            if ext in (".geojsonl",".jsonl"): return read_geojsonseq(path, display_name)
            raise ValueError("not vector")
        if isinstance(data, dict) and "objects" in data and "arcs" in data:
            # TopoJSON - convert arcs (simplified, only first object)
            return parse_topojson(data, path, display_name)
        if isinstance(data, dict) and ("features" in data or data.get("type") in ("Feature","FeatureCollection","Point","LineString","Polygon","MultiPoint","MultiLineString","MultiPolygon","GeometryCollection") or "geometries" in data):
            ds=parse_geojson_data(data, path, display_name)
            # determine driver by format of data: if features have ??? ArcGIS?
            if "features" in data and data.get("features") and isinstance(data["features"][0], dict) and "attributes" in data["features"][0]:
                # ESRIJSON
                return parse_esrijson(data, path, display_name)
            return ds
        if isinstance(data, dict) and "features" in data:
            return parse_esrijson(data, path, display_name)
    if ext in (".geojson",".json"):
        # try GeoJSON seq / esri
        return read_geojson(path, display_name)
    if ext==".shp":
        return read_shapefile(path, display_name)
    raise ValueError("not vector")

def parse_esrijson(data, path, display_name):
    # ArcGIS JSON: features with attributes/geometry (x,y or paths/rings), geometryType, spatialReference wkid
    features=[]; fields_dict={}
    sr=data.get("spatialReference",{})
    crs=None
    wkid=sr.get("wkid") or sr.get("latestWkid")
    if wkid: 
        try: crs=crs_from_epsg(int(wkid))
        except: crs=None
    field_defs=data.get("fields",[])
    fields=[]
    type_map={"esriFieldTypeOID":"Integer","esriFieldTypeInteger":"Integer","esriFieldTypeSmallInteger":"Integer","esriFieldTypeDouble":"Real","esriFieldTypeSingle":"Real","esriFieldTypeString":"String","esriFieldTypeDate":"DateTime"}
    for fd in field_defs:
        if fd.get("type")=="esriFieldTypeGeometry": continue
        fields.append(Field(fd.get("name"), type_map.get(fd.get("type"),"String")))
    geom_type_map={"esriGeometryPoint":"Point","esriGeometryMultipoint":"MultiPoint","esriGeometryPolyline":"MultiLineString","esriGeometryPolygon":"MultiPolygon"}
    gtype=geom_type_map.get(data.get("geometryType"),"Unknown")
    for i, fr in enumerate(data.get("features",[])):
        props=fr.get("attributes",{})
        geom_raw=fr.get("geometry")
        geom=None
        if geom_raw:
            if "x" in geom_raw: geom={"type":"Point","coordinates":[geom_raw["x"], geom_raw["y"]]}
            elif "points" in geom_raw: geom={"type":"MultiPoint","coordinates":geom_raw["points"]}
            elif "paths" in geom_raw: geom={"type":"LineString","coordinates":geom_raw["paths"][0]} if len(geom_raw["paths"])==1 else {"type":"MultiLineString","coordinates":geom_raw["paths"]}
            elif "rings" in geom_raw: geom={"type":"Polygon","coordinates":geom_raw["rings"]}
        features.append(Feature(i, props, geom))
        for k in props.keys():
            if k not in fields_dict: fields_dict[k]=1
    if not fields:
        order=[]
        vals={}
        for f in features:
            for k,v in f.properties.items():
                if k not in order: order.append(k); vals[k]=[]
                vals[k].append(v)
        fields=[Field(k, infer_field_type([v for v in vals[k] if v is not None])) for k in order]
    layer_name=os.path.splitext(os.path.basename(path))[0]
    layer=Layer(layer_name, gtype, fields, features, crs=crs)
    ds=VectorDataset([layer], display_name, "ESRIJSON","ESRIJSON"); return ds

def parse_topojson(data, path, display_name):
    # simplified: objects each geometry with arcs indices, transform
    transform=data.get("transform",{}); scale=transform.get("scale",[1,1]); translate=transform.get("translate",[0,0])
    arcs=data.get("arcs",[])
    def decode_arc(idx):
        reverse=False
        if idx<0: idx=~idx; reverse=True
        arc=arcs[idx]; pts=[]; x=y=0
        for i,pt in enumerate(arc):
            if i==0: x,y=pt
            else: x+=pt[0]; y+=pt[1]
            pts.append([x*scale[0]+translate[0], y*scale[1]+translate[1]])
        if reverse: pts.reverse()
        return pts
    def stitch(indices):
        line=[]
        for idx in indices:
            pts=decode_arc(idx)
            if line: pts=pts[1:]
            line.extend(pts)
        return line
    def geom_from_topo(g):
        t=g.get("type")
        if t=="Point": return {"type":"Point","coordinates":[g["coordinates"][0]*scale[0]+translate[0], g["coordinates"][1]*scale[1]+translate[1]]}
        if t=="MultiPoint": return {"type":"MultiPoint","coordinates":[[c[0]*scale[0]+translate[0], c[1]*scale[1]+translate[1]] for c in g["coordinates"]]}
        if t=="LineString": return {"type":"LineString","coordinates":stitch(g["arcs"])}
