        vals=[v for v in field_values[name] if v is not None]
        ftype=infer_field_type(vals)
        fields.append(Field(name, ftype))
    geom_type=infer_geom_type(features)
    layer=Layer(layer_name, geom_type, fields, features, crs=crs, fid_column=fid_col)
    ds=VectorDataset([layer], display_name, driver_short, driver_long)
    return ds

def read_geojsonseq(path, display_name=None):
    features_raw=[]; layer_name=os.path.splitext(os.path.basename(path))[0]
    with open(path) as f:
        for line in f:
            line=line.strip()
            if not line: continue
            # RS separator?
            if line.startswith("\x1e"): line=line[1:]
            features_raw.append(json.loads(line))
    # reuse parse logic by constructing FeatureCollection
