    if ds.layers: ds.layers[0].name=layer_name
    return ds

def write_geojson(ds, path, output_layer=None, creation_options=None):
    # only first layer? GeoJSON can have one layer. If multiple layers, GDAL writes ?? first?
    # Use layer specified or first
    layer=None
    if output_layer:
        for l in ds.layers:
