        for f in layer.features:
            props={}
            for field in layer.fields:
                v=f.properties.get(field.name)
                props[field.name]=v
            # Include extra properties not in fields in order
            for k,v in f.properties.items():
                if k not in props: props[k]=v
            feat={"type":"Feature","properties":props,"geometry":f.geometry}
            # GDAL GeoJSON writer does not write fid as feature id unless ??? It writes properties only.
            features.append(feat)
    out={}
    # Build text in GDAL style:
    # {
    # "type": "FeatureCollection",
    # "name": "test",
    # "crs": { "type": "name", "properties": { "name": "urn:ogc:def:crs:OGC:1.3:CRS84" } },
    # "features": [
    # {"type":"Feature",...},
    # ...
    # ]
    # }
    layer_name=layer.name if layer else "layer"
    crs_obj=layer.crs if layer else None
    lines=[]
    lines.append("{")
    lines.append('"type": "FeatureCollection",')
    lines.append(f'"name": {json.dumps(layer_name)},')
