            crs_name=f"urn:ogc:def:crs:EPSG::{crs_obj.epsg}"
        else:
            crs_name=None
        if crs_name:
            lines.append(f'"crs": {{ "type": "name", "properties": {{ "name": {json.dumps(crs_name)} }} }},')
    lines.append('"features": [')
    feat_strs=[]
    for feat in features:
        # geometry numbers: GeoJSON writer prints coordinates with ??? If integer-valued floats, prints 1.0 (with .0) for coordinates, properties numbers preserve ints.
        feat_strs.append(geojson_feature_str(feat))
    lines.append(",\n".join(feat_strs))
    lines.append("]")
    lines.append("}")
    dname=os.path.dirname(os.path.abspath(path)); os.makedirs(dname, exist_ok=True)
    with open(path,"w") as f: f.write("\n".join(lines)+"\n")

def geojson_num(v, is_coord=False):
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, int): 
        return str(v)+".0" if is_coord else str(v)
    if isinstance(v, float):
        if math.isnan(v): return "null"
        # GDAL prints with %.15g? Examples: 111319.490793273565941 (17 sig?). Python repr gives 111319.49079327357 (shortest) but original printed long  111319.490793273565941 in GeoJSON file (not info json). That's using printf "%.15f"? Let's see: repro.geojson coordinates "111319.490793273565941" that's ??? format with ??? GDAL GeoJSON writes coordinates using CPLString().Printf("%.15g")? 111319.49079327357 would be %.15g (15 sig). But they had 21 digits - that's "%.18f"? Hmm 111319.490793273565941 has decimal places 15(?) after decimal: 490793273565941 =15 decimal digits. So format %.15f for coordinates? For 1.0 it gives 1.000000000000000 but they printed 1.0 (trim trailing zeros?). So GDAL uses OGRCoordinateRepr (?) which prints with 15 decimal places then trims trailing zeros but keeps .0
        # We'll implement: format with repr for json info, but for GeoJSON file coordinates use: ('%.15f' % v).rstrip('0') ensuring decimal point.
        s=('%.15f' % v)
        # This for large numbers may differ in last digits due binary representation - %.15f in C will produce same as python (both binary)
        if '.' in s: s=s.rstrip('0'); 
        if s.endswith('.'): s+='0'
        if s=='-0.0' or s=='-0': s='0.0'
        return s
    return json.dumps(v)

def geojson_feature_str(feat):
    # {"type":"Feature","properties":{...},"geometry":{...}}
    props=feat.get("properties") or {}
    prop_parts=[]
    for k,v in props.items():
        prop_parts.append(f"{json.dumps(k)}:{geojson_value_str(v, False)}")
    props_str="{"+",".join(prop_parts)+"}"
    geom=feat.get("geometry")
    geom_str=geojson_geom_str(geom)
    return f'{{"type":"Feature","properties":{props_str},"geometry":{geom_str}}}'

def geojson_value_str(v, is_coord):
    if v is None: return "null"
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, (int,float)): return geojson_num(v, is_coord)
    if isinstance(v, str): return json.dumps(v, ensure_ascii=False)
    if isinstance(v, list): return "["+",".join(geojson_value_str(e, is_coord) for e in v)+"]"
    if isinstance(v, dict): return "{"+",".join(json.dumps(k)+":"+geojson_value_str(val, is_coord) for k,val in v.items())+"}"
    return json.dumps(str(v))

def geojson_geom_str(geom):
    if geom is None: return "null"
    t=geom.get("type")
    if t=="GeometryCollection":
        inner=",".join(geojson_geom_str(g) for g in geom.get("geometries",[]))
        return f'{{"type":"GeometryCollection","geometries":[{inner}]}}'
    coords=geom.get("coordinates")
    return f'{{"type":{json.dumps(t)},"coordinates":{geojson_value_str(coords, True)}}}'

def write_geojsonseq(ds, path, output_layer=None):
    layer=ds.layers[0] if ds.layers else Layer("layer")
    if output_layer:
        for l in ds.layers:
            if l.name==output_layer: layer=l
    lines=[]
    for f in layer.features:
