def parse_topojson(data, path, display_name):
    # simplified: objects each geometry with arcs indices, transform
    transform=data.get("transform",{}); scale=transform.get("scale",[1,1]); translate=transform.get("translate",[0,0])
    arcs=data.get("arcs",[])
    def decode_arc(idx):
        reverse=False
        if idx<0: idx=~idx; reverse=True
        arc=arcs[idx]; pts=[]; x=y=0
        for i,pt in enumerate(arc):
            if i==0: x,y=pt
            else: x+=pt[0]; y+=pt[1]
            pts.append([x*scale[0]+translate[0], y*scale[1]+translate[1]])
        if reverse: pts.reverse()
        return pts
    def stitch(indices):
        line=[]
        for idx in indices:
            pts=decode_arc(idx)
            if line: pts=pts[1:]
            line.extend(pts)
        return line
    def geom_from_topo(g):
        t=g.get("type")
        if t=="Point": return {"type":"Point","coordinates":[g["coordinates"][0]*scale[0]+translate[0], g["coordinates"][1]*scale[1]+translate[1]]}
        if t=="MultiPoint": return {"type":"MultiPoint","coordinates":[[c[0]*scale[0]+translate[0], c[1]*scale[1]+translate[1]] for c in g["coordinates"]]}
        if t=="LineString": return {"type":"LineString","coordinates":stitch(g["arcs"])}
        if t=="MultiLineString": return {"type":"MultiLineString","coordinates":[stitch(a) for a in g["arcs"]]}
        if t=="Polygon": return {"type":"Polygon","coordinates":[stitch(ring) for ring in g["arcs"]]}
        if t=="MultiPolygon": return {"type":"MultiPolygon","coordinates":[[stitch(ring) for ring in poly] for poly in g["arcs"]]}
        if t=="GeometryCollection": return {"type":"GeometryCollection","geometries":[geom_from_topo(sub) for sub in g.get("geometries",[])]}
        return None
    layers=[]
    for obj_name, obj in data.get("objects",{}).items():
        geoms=[]
        if obj.get("type")=="GeometryCollection": geoms=obj.get("geometries",[])
        else: geoms=[obj]
        features=[]; field_order=[]; vals={}
        for i,g in enumerate(geoms):
            props=g.get("properties",{}) or {}
            for k,v in props.items():
                if k not in field_order: field_order.append(k); vals[k]=[]
                vals[k].append(v)
            fid=g.get("id", i)
            features.append(Feature(fid if isinstance(fid,int) else i, props, geom_from_topo(g)))
        fields=[Field(k, infer_field_type([v for v in vals[k] if v is not None])) for k in field_order]
        layers.append(Layer(obj_name, infer_geom_type(features), fields, features, crs=crs_from_epsg(4326, variant="crs84")))
    ds=VectorDataset(layers, display_name, "TopoJSON","TopoJSON"); return ds

