def compute_histogram(raster, band):
    # Determine min/max for histogram: if band dtype integer range etc.
    vals=band_valid_values(band,raster)
    if band.dtype in ("Byte",):
        mn=-0.5; mx=255.5; nb=256
    else:
        stats=stored_band_stats(band) or (compute_band_stats(raster,band) if vals else None)
        if not stats: return None
        mn=stats["min"]; mx=stats["max"]
