def format_dms(value, is_lon):
    # value degrees
    hem=""
    if is_lon: hem="E" if value>=0 else "W"
    else: hem="N" if value>=0 else "S"
    av=abs(value)
    deg=int(math.floor(av+1e-12)); rem=(av-deg)*60; minv=int(math.floor(rem+1e-12)); sec=(rem-minv)*60
    # GDAL shows 0.01" for zero due proj epsilon
    if av < 1e-12: sec=0.01
    else:
        # Round sec to 2 decimals, handling carry
        sec_r=round(sec+1e-9,2)
        if sec_r>=60: sec_r-=60; minv+=1
        if minv>=60: minv-=60; deg+=1
        sec=sec_r
    s=f"{deg}d {minv}' {sec:.2f}\"{hem}"
    return s

