# ---------- Statistics / histogram ----------
def band_valid_values(band, raster=None):
    vals=[]
    for v in band.data:
        if isinstance(v, complex):
            vals.append(abs(v)); continue
        if band.nodata is not None:
            if isinstance(band.nodata,float) and math.isnan(band.nodata):
                if isinstance(v,float) and math.isnan(v): continue
            elif float(v)==float(band.nodata): continue
        if isinstance(v,float) and math.isnan(v):
            # If nodata is nan already excluded; otherwise GDAL treats nan as nodata? For Float bands without nodata, NaN pixels are excluded from stats.
            continue
        vals.append(float(v))
    return vals

def compute_band_stats(raster, band, approx=False):
    vals=band_valid_values(band, raster)
    total=len(band.data) if band.data else 0
    if not vals:
        return None
    mn=min(vals); mx=max(vals); mean=sum(vals)/len(vals)
    var=sum((x-mean)**2 for x in vals)/len(vals); std=math.sqrt(var)
    valid_percent=100.0*len(vals)/total if total else 0
    def fmt(v):
        if isinstance(v,float) and math.isnan(v): return "nan"
        if v==int(v) and abs(v)<1e16: return str(int(v))
        return ('%.15g' % v)
    # insert order min max mean std valid
    new_md={}
    # preserve non-stat keys? GDAL ordering for computed: stats first as above, then other metadata (?)
    new_md["STATISTICS_MINIMUM"]=fmt(mn); new_md["STATISTICS_MAXIMUM"]=fmt(mx); new_md["STATISTICS_MEAN"]=fmt(mean); new_md["STATISTICS_STDDEV"]=fmt(std); new_md["STATISTICS_VALID_PERCENT"]=fmt(valid_percent)
    for k,v in band.metadata.items():
        if k not in new_md: new_md[k]=v
    band.metadata=new_md
    band._stats_computed=True
    return {"min":mn,"max":mx,"mean":mean,"std":std,"valid_percent":valid_percent}

def stored_band_stats(band):
    if "STATISTICS_MINIMUM" in band.metadata and "STATISTICS_MAXIMUM" in band.metadata:
        try:
            return {"min":float(band.metadata["STATISTICS_MINIMUM"]), "max":float(band.metadata["STATISTICS_MAXIMUM"]), "mean":float(band.metadata.get("STATISTICS_MEAN",0)), "std":float(band.metadata.get("STATISTICS_STDDEV",0))}
        except: return None
    return None

def compute_histogram(raster, band):
    # Determine min/max for histogram: if band dtype integer range etc.
    vals=band_valid_values(band,raster)
    if band.dtype in ("Byte",):
        mn=-0.5; mx=255.5; nb=256
    else:
        stats=stored_band_stats(band) or (compute_band_stats(raster,band) if vals else None)
        if not stats: return None
        mn=stats["min"]; mx=stats["max"]
        if mn==mx: mx=mn+1
        nb=256
    buckets=[0]*nb
    if nb==256 and band.dtype=="Byte":
        for v in vals:
            idx=int(v+0.5) # bucket -0.5 to 255.5 each integer
            if 0 <= idx < nb: buckets[idx]+=1
    else:
        for v in vals:
            idx=int((v-mn)/(mx-mn)*nb) if mx!=mn else 0
            if idx>=nb: idx=nb-1
            if idx<0: idx=0
            buckets[idx]+=1
    return {"count":nb,"min":mn,"max":mx,"buckets":buckets}

