def eval_where(expr, props, fields=None):
    if expr is None or expr=="": return True
    # @filename handled by caller
    # Tokenizer and recursive descent
    # Support: OR, AND, NOT, parentheses, comparisons, IS [NOT] NULL, IN (...), LIKE, BETWEEN?
    tokens=[]
    i=0
    s=expr
    while i < len(s):
        if s[i].isspace(): i+=1; continue
        if s[i] in "(),": tokens.append(s[i]); i+=1; continue
        if s[i:i+2] in (">=","<=","!=","<>"): tokens.append(s[i:i+2]); i+=2; continue
        if s[i] in "=><": tokens.append(s[i]); i+=1; continue
        if s[i]=="'":
            j=i+1; buf=""
            while j < len(s):
                if s[j]=="'":
                    if j+1 < len(s) and s[j+1]=="'": buf+="'"; j+=2; continue
                    break
                buf+=s[j]; j+=1
            tokens.append(("STR",buf)); i=j+1; continue
        if s[i]=='"':
            j=s.find('"', i+1); tokens.append(("IDENT", s[i+1:j])); i=j+1; continue
        m=re.match(r'-?\d+\.?\d*(?:[eE][+-]?\d+)?', s[i:])
        if m and (s[i].isdigit() or s[i]=='-'):
            txt=m.group(0); tokens.append(("NUM", float(txt) if '.' in txt or 'e' in txt.lower() else int(txt))); i+=len(txt); continue
        m=re.match(r'[A-Za-z_][A-Za-z0-9_\.]*', s[i:])
        if m:
            word=m.group(0); up=word.upper()
            if up in ("AND","OR","NOT","IS","NULL","IN","LIKE","BETWEEN"): tokens.append(up)
            elif up=="TRUE": tokens.append(("NUM",1))
            elif up=="FALSE": tokens.append(("NUM",0))
            else: tokens.append(("IDENT",word))
            i+=len(word); continue
        i+=1
    pos=[0]
    def peek(): return tokens[pos[0]] if pos[0] < len(tokens) else None
    def eat():
        t=tokens[pos[0]]; pos[0]+=1; return t
    def parse_or():
        v=parse_and()
        while peek()=="OR":
            eat(); rhs=parse_and(); v= bool(v or rhs)
        return v
    def parse_and():
        v=parse_not()
        while peek()=="AND":
            eat(); rhs=parse_not(); v=bool(v and rhs)
        return v
    def parse_not():
        if peek()=="NOT": eat(); return not parse_not()
        return parse_atom()
    def parse_atom():
        if peek()=="(":
            eat(); v=parse_or(); 
            if peek()==")": eat()
            return v
        # left value
        left=parse_value()
        tok=peek()
        if tok=="IS":
            eat(); not_flag=False
            if peek()=="NOT": eat(); not_flag=True
            if peek()=="NULL": eat()
            res=(left is None)
            return (not res) if not_flag else res
        if tok=="IN":
            eat(); 
            if peek()=="(": eat()
            vals=[]
            while peek()!=")" and peek() is not None:
                vals.append(parse_value())
                if peek()==",": eat()
            if peek()==")": eat()
            return left in vals
        if tok=="LIKE":
            eat(); pattern=parse_value()
            if left is None or pattern is None: return False
            pat=re.escape(str(pattern)).replace("%",".*").replace("_",".")
            return re.match("^"+pat+"$", str(left)) is not None
        if tok=="BETWEEN":
            eat(); low=parse_value(); 
            if peek()=="AND": eat()
            high=parse_value(); return left is not None and low <= left <= high
        if tok in ("=","!=","<>",">","<",">=","<="):
            eat(); right=parse_value()
            if left is None or right is None: return False
            try:
                if tok=="=": return left==right
                if tok in ("!=","<>"): return left!=right
                if tok==">": return left>right
                if tok=="<": return left<right
                if tok==">=": return left>=right
                if tok=="<=": return left<=right
            except Exception: return False
        return bool(left)
    def parse_value():
        tok=peek()
        if tok is None: return None
        if isinstance(tok, tuple):
            eat()
            if tok[0]=="STR": return tok[1]
            if tok[0]=="NUM": return tok[1]
            if tok[0]=="IDENT":
                # field name - try props keys case-insensitive
                name=tok[1]
                if name in props: return props[name]
                for k,v in props.items():
                    if k.lower()==name.lower(): return v
                return None
        if tok=="NULL": eat(); return None
        # unary minus already incorporated in numbers
        eat(); return tok
    try:
        return parse_or()
    except Exception:
        return False

def parse_sql_select(sql):
    # returns dict fields, from, where, order_by, limit etc
    s=sql.strip().rstrip(";")
    m=re.match(r'(?is)^SELECT\s+(.*?)\s+FROM\s+([^\s]+)(?:\s+WHERE\s+(.*?))?(?:\s+ORDER\s+BY\s+(.*?))?(?:\s+LIMIT\s+(\d+))?\s*$', s)
    if not m: return None
    fields_part=m.group(1).strip(); from_part=m.group(2).strip().strip('"'); where=m.group(3); order=m.group(4); limit=m.group(5)
    if fields_part=="*": fields=None
    else: fields=[f.strip().strip('"') for f in fields_part.split(",")]
    return {"fields":fields,"from":from_part,"where":where,"order":order,"limit":int(limit) if limit else None}

