    return r

def gt_apply(gt, x,y): return (gt[0]+x*gt[1]+y*gt[2], gt[3]+x*gt[4]+y*gt[5])
def gt_inverse(gt):
    det=gt[1]*gt[5]-gt[2]*gt[4]
    if det==0: return None
    # inverse mapping: [px, py] = ...
    def inv(X,Y):
        dx=X-gt[0]; dy=Y-gt[3]
        px=(gt[5]*dx - gt[2]*dy)/det; py=(-gt[4]*dx + gt[1]*dy)/det
        return (px,py)
    return inv

def resample_raster(src, dst_w, dst_h, dst_gt, resampling="near", dst_crs=None, src_nodata_handling=True):
    # Create output bands sampling src at dst pixel centers transform: if CRS differs, transform dst geo center to src CRS then to src pixel
    inv=gt_inverse(src.default_gt())
    out_bands=[]
