        data=[]
        for y in range(dst_h):
            for x in range(dst_w):
                geo=gt_apply(dst_gt, x+0.5, y+0.5)
                if dst_crs is not None and src.crs is not None and (dst_crs.epsg!=src.crs.epsg):
                    # geo is in dst CRS, convert to src CRS via lonlat
                    lonlat=crs_to_lonlat(geo[0], geo[1], dst_crs)
                    geo2=lonlat_to_crs(lonlat[0], lonlat[1], src.crs)
