def sample_band(band, px, py, resampling="near"):
    # px,py are continuous pixel coordinates where pixel (i) covers [i,i+1) center i+0.5 . So sampling coordinates given as ... resample passes px from inverse of geo center - that's in pixel space where integer are corner. Nearest pixel index = floor(px)
    w=band.w; h=band.h
    if resampling in ("near","nearest","nearestNeighbour","mode","max","min","med","q1","q3","average","rms","sum"):
        ix=int(math.floor(px)); iy=int(math.floor(py))
        if ix<0 or ix>=w or iy<0 or iy>=h:
            return band.nodata if band.nodata is not None else cast_value(0, band.dtype)
        if resampling in ("near","nearest"): return band.data[iy*w+ix]
        # for other resampling in warp context, they aggregate area - approximate nearest
        return band.data[iy*w+ix]
    if resampling in ("bilinear",):
        # convert to index space where pixel centers are integer: u=px-0.5
        u=px-0.5; v=py-0.5; x0=int(math.floor(u)); y0=int(math.floor(v)); fx=u-x0; fy=v-y0
        total=0.0; wsum=0.0
        for dy in (0,1):
            for dx in (0,1):
                xx=x0+dx; yy=y0+dy
                weight=(fx if dx else 1-fx)*(fy if dy else 1-fy)
                if 0 <= xx < w and 0 <= yy < h:
                    val=band.data[yy*w+xx]
                    if band.nodata is not None and float(val)==float(band.nodata): continue
                    total+=float(val)*weight; wsum+=weight
        if wsum==0: return band.nodata if band.nodata is not None else cast_value(0,band.dtype)
        return total/wsum
    if resampling in ("cubic","cubicspline","lanczos"):
        # approximate bilinear for cubic
        return sample_band(band, px, py, "bilinear")
    # average etc fallback nearest
    ix=int(math.floor(px)); iy=int(math.floor(py))
    if ix<0 or ix>=w or iy<0 or iy>=h: return band.nodata if band.nodata is not None else cast_value(0,band.dtype)
    return band.data[iy*w+ix]

