def determine_driver(path):
    if not os.path.exists(path): return None
    if os.path.isdir(path):
        # Directory datasets: Shapefile dir? Or ???
        # Check for .shp inside maybe identified as ESRI Shapefile? Or if contains .?? 
        return None
    ext=os.path.splitext(path)[1].lower()
    try:
        with open(path,"rb") as f: head=f.read(2048)
    except: return None
    if head[:2] in (b'II',b'MM'):
        # Could be GTiff
        return "GTiff"
    stripped=head.lstrip()
    if stripped.startswith(b'<'):
        # XML could be VRT
        if b'<VRTDataset' in head[:500]: return "VRT"
        return None
    if ext==".shp" or (len(head)>=4 and struct.unpack('>i', head[:4])[0]==9994):
        return "ESRI Shapefile"
    if stripped.startswith(b'{') or stripped.startswith(b'['):
        # JSON
        try:
            txt=open(path,encoding="utf-8").read()
            data=json.loads(txt)
        except:
            # lines
            if ext in (".geojsonl",".geojsons"): return "GeoJSONSeq"
            return None
        if isinstance(data, dict) and "objects" in data and "arcs" in data: return "TopoJSON"
        if isinstance(data, dict) and "features" in data and data["features"] and isinstance(data["features"][0], dict) and "attributes" in data["features"][0]: return "ESRIJSON"
        return "GeoJSON"
    if ext in (".geojsonl",".geojsons"): return "GeoJSONSeq"
    if ext in (".tif",".tiff"): return "GTiff"  # if magic failed maybe ?
    if ext==".vrt": return "VRT"
    if ext in (".geojson",".json"): return "GeoJSON"
    if ext==".dbf": return "ESRI Shapefile"
    return None

