def solve3(A,b):
    # Gaussian elimination 3x3
    n=3; M=[row[:]+[b[i]] for i,row in enumerate(A)]
    for i in range(n):
        piv=max(range(i,n), key=lambda r: abs(M[r][i])); 
        if abs(M[piv][i])<1e-12: raise ValueError("singular")
        M[i],M[piv]=M[piv],M[i]
        div=M[i][i]
        for j in range(i, n+1): M[i][j]/=div
        for r in range(n):
            if r!=i:
                factor=M[r][i]
                for j in range(i,n+1): M[r][j]-=factor*M[i][j]
    return [M[i][n] for i in range(n)]

