            for i in range(1,len(points)-1):
                d=perp_dist(points[i],a,b)
                if d>maxd: maxd=d; idx=i
            if maxd>tol:
                left=rec(points[:idx+1]); right=rec(points[idx:]); return left[:-1]+right
            else: return [a,b]
        return rec(pts)
    t=geom.get("type")
    if t=="LineString": return {"type":"LineString","coordinates":simplify_line(geom["coordinates"])}
    if t=="Polygon": return {"type":"Polygon","coordinates":[simplify_line(r) for r in geom["coordinates"]]}
    if t=="MultiLineString": return {"type":"MultiLineString","coordinates":[simplify_line(l) for l in geom["coordinates"]]}
    if t=="MultiPolygon": return {"type":"MultiPolygon","coordinates":[[simplify_line(r) for r in poly] for poly in geom["coordinates"]]}
    return geom

def segmentize_geometry(geom, max_len):
    if geom is None or max_len<=0: return geom
    def seg_line(pts):
        out=[pts[0]]
        for a,b in zip(pts, pts[1:]):
            dist=math.hypot(b[0]-a[0], b[1]-a[1])
            if dist>max_len:
                n=int(math.ceil(dist/max_len))
                for i in range(1,n): out.append([a[0]+(b[0]-a[0])*i/n, a[1]+(b[1]-a[1])*i/n])
            out.append(b)
        return out
    t=geom.get("type")
    if t=="LineString": return {"type":"LineString","coordinates":seg_line(geom["coordinates"])}
    if t=="Polygon": return {"type":"Polygon","coordinates":[seg_line(r) for r in geom["coordinates"]]}
    if t=="MultiLineString": return {"type":"MultiLineString","coordinates":[seg_line(l) for l in geom["coordinates"]]}
    if t=="MultiPolygon": return {"type":"MultiPolygon","coordinates":[[seg_line(r) for r in poly] for poly in geom["coordinates"]]}
    return geom

def is_valid_geometry(geom):
    if geom is None: return True
    t=geom.get("type")
    if t=="Polygon":
        for ring in geom["coordinates"]:
            if len(ring)<4: return False
            if ring[0]!=ring[-1]: return False
            # self intersection check brute for nonadjacent segments
            if ring_self_intersects(ring): return False
    if t=="MultiPolygon":
        for poly in geom["coordinates"]:
            for ring in poly:
                if len(ring)<4 or ring[0]!=ring[-1]: return False
    return True

def ring_self_intersects(ring):
    def seg_int(p1,p2,p3,p4):
        def orient(a,b,c): return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
        o1=orient(p1,p2,p3); o2=orient(p1,p2,p4); o3=orient(p3,p4,p1); o4=orient(p3,p4,p2)
        return o1*o2<0 and o3*o4<0
    n=len(ring)-1
    for i in range(n):
        for j in range(i+2,n):
            if i==0 and j==n-1: continue
            if seg_int(ring[i],ring[i+1],ring[j],ring[j+1]): return True
    return False

def make_valid_geometry(geom):
    if geom is None: return None
    if geom.get("type")=="Polygon":
        new_rings=[]
        for ring in geom["coordinates"]:
            if ring[0]!=ring[-1]: ring=ring+[ring[0]]
            if len(ring)>=4: new_rings.append(ring)
        if new_rings: return {"type":"Polygon","coordinates":new_rings}
        return None
    return geom

def explode_geometry(geom):
    if geom is None: return []
    t=geom.get("type")
    if t=="MultiPoint": return [{"type":"Point","coordinates":p} for p in geom["coordinates"]]
    if t=="MultiLineString": return [{"type":"LineString","coordinates":l} for l in geom["coordinates"]]
    if t=="MultiPolygon": return [{"type":"Polygon","coordinates":p} for p in geom["coordinates"]]
    if t=="GeometryCollection": 
        out=[]
        for g in geom["geometries"]: out.extend(explode_geometry(g))
        return out
    return [geom]

def combine_geometries(geoms, dissolve=False):
    if not geoms: return None
    types=set(g["type"] for g in geoms)
    if types=={"Point"}: return {"type":"MultiPoint","coordinates":[g["coordinates"] for g in geoms]}
    if types=={"LineString"}: return {"type":"MultiLineString","coordinates":[g["coordinates"] for g in geoms]}
    if types=={"Polygon"}: return {"type":"MultiPolygon","coordinates":[g["coordinates"] for g in geoms]}
    if len(geoms)==1: return geoms[0]
    return {"type":"GeometryCollection","geometries":geoms}

def promote_to_multi(geom):
    if geom is None: return None
    t=geom["type"]
    if t=="Point": return {"type":"MultiPoint","coordinates":[geom["coordinates"]]}
    if t=="LineString": return {"type":"MultiLineString","coordinates":[geom["coordinates"]]}
    if t=="Polygon": return {"type":"MultiPolygon","coordinates":[geom["coordinates"]]}
    return geom
def demote_from_multi(geom):
    if geom is None: return None
    t=geom["type"]
    if t=="MultiPoint" and len(geom["coordinates"])>=1: return {"type":"Point","coordinates":geom["coordinates"][0]}
    if t=="MultiLineString" and len(geom["coordinates"])>=1: return {"type":"LineString","coordinates":geom["coordinates"][0]}
    if t=="MultiPolygon" and len(geom["coordinates"])>=1: return {"type":"Polygon","coordinates":geom["coordinates"][0]}
    return geom

def geometry_intersects_bbox(geom, clip_geom):
    if geom is None: return False
    # check extent intersection or point in clip
    coords=geom_coords(geom); 
    if not coords: return False
    # point in clip for first point or extent overlap approx
    for x,y in coords:
        if point_in_geometry(x,y,clip_geom): return True
    # clip extent centre
    cc=geom_coords(clip_geom)
    if cc:
        # check clip vertices inside geom (for surrounding polygon)
        for x,y in cc:
            if point_in_geometry(x,y,geom): return True
    return False

def clip_geometry_to_bbox(geom, bbox):
    if geom is None: return None
    xmin,ymin,xmax,ymax=bbox
    t=geom.get("type")
    if t=="Point":
        x,y=geom["coordinates"][:2]
        return geom if xmin<=x<=xmax and ymin<=y<=ymax else None
    if t=="Polygon":
        # Sutherland-Hodgman per ring
        def clip_ring(ring):
            def clip_edge(poly, inside_func, intersect):
                out=[]
                if not poly: return out
                for i in range(len(poly)):
                    cur=poly[i]; prev=poly[i-1]
                    cur_in=inside_func(cur); prev_in=inside_func(prev)
                    if cur_in and prev_in: out.append(cur)
                    elif prev_in and not cur_in: out.append(intersect(prev,cur))
                    elif not prev_in and cur_in: out.append(intersect(prev,cur)); out.append(cur)
                return out
            poly=ring[:-1] if ring and ring[0]==ring[-1] else ring[:]
            # left
            poly=clip_edge(poly, lambda p:p[0]>=xmin, lambda a,b: [xmin, a[1]+(b[1]-a[1])*(xmin-a[0])/(b[0]-a[0]) if b[0]!=a[0] else a[1]])
            poly=clip_edge(poly, lambda p:p[0]<=xmax, lambda a,b: [xmax, a[1]+(b[1]-a[1])*(xmax-a[0])/(b[0]-a[0]) if b[0]!=a[0] else a[1]])
            poly=clip_edge(poly, lambda p:p[1]>=ymin, lambda a,b: [a[0]+(b[0]-a[0])*(ymin-a[1])/(b[1]-a[1]) if b[1]!=a[1] else a[0], ymin])
            poly=clip_edge(poly, lambda p:p[1]<=ymax, lambda a,b: [a[0]+(b[0]-a[0])*(ymax-a[1])/(b[1]-a[1]) if b[1]!=a[1] else a[0], ymax])
            if poly: poly.append(list(poly[0]))
            return poly
        rings=[clip_ring(r) for r in geom["coordinates"]]
        rings=[r for r in rings if len(r)>=4]
        return {"type":"Polygon","coordinates":rings} if rings else None
    # lines/other: filter - keep whole if intersects
    return geom

def do_vector_concat(datasets, o, parsed):
    # mode: merge etc
    layers_by_name={}
    order=[]
    for ds in datasets:
        for layer in ds.layers:
            name=o.get("output-layer") or layer.name
            if name not in layers_by_name:
                layers_by_name[name]=Layer(name, layer.geometry_type, [f.copy() for f in layer.fields], [], crs=layer.crs, fid_column=layer.fid_column)
                order.append(name)
            target=layers_by_name[name]
            # field strategy: first / union etc - default keep first fields, add missing if union?
            existing=[f.name for f in target.fields]
            for fld in layer.fields:
                if fld.name not in existing: target.fields.append(fld.copy()); existing.append(fld.name)
            fid_start=len(target.features)
            for i,f in enumerate(layer.features):
                nf=Feature(f.fid if False else len(target.features), dict(f.properties), deepcopy(f.geometry))
                # source-layer field
                if o.get("source-layer-field-name"):
                    nf.properties[o["source-layer-field-name"]]=layer.name if o.get("source-layer-field-content")!="basename" else layer.name
                target.features.append(nf)
            # CRS keep first
    return VectorDataset([layers_by_name[n] for n in order], "", "GeoJSON","GeoJSON")

def do_vector_partition(ds, o, parsed, path_key, invoked):
    # Output is a dataset with pattern ... It writes multiple files based on field value.
    field=o.get("field")
    output_base=o.get("output")
    pattern=o.get("pattern") or "{field}_{value}" # approx
    # Group by field
    groups={}
    for layer in ds.layers:
        for f in layer.features:
            key=f.properties.get(field) if field else "all"
            groups.setdefault(key, []).append(f)
    # Write each partition as its own file using pattern substitution
    # Pattern syntax GDAL: e.g., "%{field_name}" ??? We'll support {value} and %field%?
    for key, feats in groups.items():
        # Create filename
        fn=pattern
        fn=fn.replace("{value}", str(key)).replace("%value%", str(key))
        if field: fn=fn.replace("{field}", field)
        # If pattern doesn't include extension, output may be a directory template: e.g., output is a template string itself? Spec: partition output is positional 'output' which is a filename template, not parsed as file? Our handler treats output as base - GDAL partition: output argument is a template like "out_{}.geojson"
        out_name=output_base
        # If output_base contains pattern placeholders, use it as template
        if "{" in str(output_base) or "%" in str(output_base):
            out_name=str(output_base).replace("{value}", str(key))
            if field: 
                # placeholder for field value in template may be field name like "{id}"
                out_name=out_name.replace("{"+field+"}", str(key))
        else:
            # output is directory
            ext=".geojson"
            # guess from ??? Use pattern filename
            out_name=os.path.join(str(output_base), f"{field}_{key}{ext}")
        sub_ds=VectorDataset([Layer(ds.layers[0].name, ds.layers[0].geometry_type, ds.layers[0].fields, feats, crs=ds.layers[0].crs)], out_name, "GeoJSON","GeoJSON")
        # Write without overwrite check (create dir)
        dname=os.path.dirname(os.path.abspath(out_name)); os.makedirs(dname, exist_ok=True)
        write_vector(sub_ds, out_name, o.get("output-format"), o.get("output-layer"))
    return None

def do_vector_rasterize(ds, o, parsed, path_key, invoked):
    # Burn vector into raster: either modify existing raster (if --update?) or create new with extent/resolution/size/crs
    # Determine output raster geometry
    output=o.get("output")
    # If input raster like? rasterize may have --like? no.
    extent=o.get("extent")  # xmin ymin xmax ymax
    resolution=o.get("resolution"); size=o.get("size")
    # If extent not given, use layer extent
    layers=ds.layers
    if o.get("input-layer"):
        names=o["input-layer"] if isinstance(o["input-layer"],list) else [o["input-layer"]]
        layers=[l for l in layers if l.name in names]
    ext=None
    for l in layers:
        e=l.extent()
        if e:
            if ext is None: ext=e
            else: ext=[min(ext[0],e[0]),min(ext[1],e[1]),max(ext[2],e[2]),max(ext[3],e[3])]
    if extent:
        ext=[float(x) for x in extent]
    if ext is None: ext=[0,0,1,1]
    xmin,ymin,xmax,ymax=ext
    width=height=None
    if size:
        sz=size if isinstance(size,list) else str(size).split(",")
        width=int(float(sz[0])); height=int(float(sz[1]))
    elif resolution:
        rx,ry=(float(resolution[0]),float(resolution[1])) if isinstance(resolution,list) and len(resolution)>=2 else (float(resolution),float(resolution))
        width=int(round((xmax-xmin)/rx)); height=int(round((ymax-ymin)/ry))
    else:
        width=256; height=256
        # GDAL default if nothing specified is error? But choose based on extent  ... maybe it requires size/resolution/extent - if missing, GDAL errors. We'll keep.
    if width<=0: width=1
    if height<=0: height=1
    gt=(xmin, (xmax-xmin)/width,0, ymax,0,-(ymax-ymin)/height)
    crs=None
    if o.get("crs"): crs=parse_crs_string(o["crs"], path_key, invoked)
    elif layers and layers[0].crs: crs=layers[0].crs
    dtype=canonical_dtype(o.get("output-data-type") or "Byte")
    band_count=len(o.get("band") or [1]) if False else 1
    # bands: rasterize can create multiple bands if --band repeated? Assume 1
    init_val=0
    if o.get("init"):
        iv=o["init"]; init_val=float(iv[0] if isinstance(iv,list) else iv)
    nodata_val=parse_nodata_value(o["nodata"]) if o.get("nodata") is not None else None
    base_data=[cast_value(nodata_val if nodata_val is not None and o.get("init") is None else init_val, dtype)]*(width*height)
    # If nodata and no init, dataset band nodata set and background is nodata?
    # burn values
    burns=o.get("burn") or []
    if isinstance(burns,(int,float,str)): burns=[burns]
    attribute=o.get("attribute-name")
    # where filter
    where=o.get("where")
    sql=o.get("sql")
    raster_data=list(base_data)
    # Rasterize each feature (points/lines/polys)
    all_touched=bool(o.get("all-touched"))
    for layer in layers:
        feats=layer.features
        if where: feats=[f for f in feats if eval_where(where, f.properties)]
        if sql:
            # sql applies to dataset - approximate filter using apply_sql
            tmp_ds=apply_sql_to_ds(VectorDataset([layer], ds.filename, ds.driver_short, ds.driver_long), sql, {}, path_key, invoked)
            feats=tmp_ds.layers[0].features
        for fi,f in enumerate(feats):
            if attribute: burn_val=f.properties.get(attribute)
            elif burns: burn_val=float(burns[0] if len(burns)==1 else burns[fi % len(burns)])
            else: burn_val=1
            if burn_val is None: continue
            # Fill
            geom=f.geometry
            if geom is None: continue
            # Points / lines / polygons
            coords=geom_coords(geom)
            # Pixel loop bounding box
            if not coords: continue
            # For polygons, fill point-in-poly; for lines draw line pixels; points single pixel
            gxmin=min(c[0] for c in coords); gxmax=max(c[0] for c in coords); gymin=min(c[1] for c in coords); gymax=max(c[1] for c in coords)
            # Convert geo bbox to pixel bbox
            px0=int(math.floor((gxmin-xmin)/((xmax-xmin)/width))); px1=int(math.floor((gxmax-xmin)/((xmax-xmin)/width)))
            py0=int(math.floor((ymax-gymax)/((ymax-ymin)/height))); py1=int(math.floor((ymax-gymin)/((ymax-ymin)/height)))
            for py in range(max(0,py0), min(height, py1+1)):
                for px in range(max(0,px0), min(width, px1+1)):
                    cx=xmin+(px+0.5)*(xmax-xmin)/width; cy=ymax-(py+0.5)*(ymax-ymin)/height
                    inside=False
                    if geom.get("type") in ("Polygon","MultiPolygon"): inside=point_in_geometry(cx,cy,geom)
                    elif geom.get("type")=="Point": inside=(int((geom["coordinates"][0]-xmin)/((xmax-xmin)/width))==px and int((ymax-geom["coordinates"][1])/((ymax-ymin)/height))==py)
                    elif geom.get("type") in ("LineString","MultiLineString"): inside=True if (px>=px0 and px<=px1 and py>=py0 and py<=py1) else False # simplify: draw bbox? We'll draw lines segments below instead
                    else: inside=point_in_geometry(cx,cy,geom) if geom.get("type") else False
                    if geom.get("type") in ("LineString","MultiLineString"):
                        # draw by checking distance to segments (within half pixel)
                        inside=False
                        lines= [geom["coordinates"]] if geom["type"]=="LineString" else geom["coordinates"]
                        for line in lines:
                            for a,b in zip(line, line[1:]):
                                # distance point segment
                                if dist_point_segment((cx,cy), a,b) <= max((xmax-xmin)/width, (ymax-ymin)/height)/1.5: inside=True
                    if inside:
                        raster_data[py*width+px]=cast_value(burn_val, dtype)
    band=Band(dtype=dtype,w=width,h=height,data=raster_data, nodata=nodata_val, color_interp="Gray")
    raster=Raster(w=width,h=height,bands=[band],filename=output or "",driver_short="GTiff",driver_long="GeoTIFF",gt=gt,has_gt=True,crs=crs,metadata={"IMAGE_STRUCTURE":{"INTERLEAVE":"BAND"}})
    if output:
        write_output_raster(path_key, invoked, parsed, raster, output, {"output-format":o.get("output-format"),"creation-option":o.get("creation-option")})
        emit_progress(parsed, path_key)
    return raster

def dist_point_segment(p,a,b):
    px,py=p; ax,ay=a[:2]; bx,by=b[:2]
    l2=(bx-ax)**2+(by-ay)**2
    if l2==0: return math.hypot(px-ax,py-ay)
    t=max(0,min(1,((px-ax)*(bx-ax)+(py-ay)*(by-ay))/l2))
    return math.hypot(px-(ax+t*(bx-ax)), py-(ay+t*(by-ay)))

def do_layer_algebra(ds, other_ds, op_name, o):
    # Very simplified: intersection/union/difference based on bbox? Use point filtering etc.
    # Assume first layer A, second B geometries used as filter/mask for operations like intersection/clip for points; for polygons approximated as filter features intersecting any B and keep/clip to B bbox.
    if not ds.layers or not other_ds.layers: return ds
    layer=ds.layers[0]; other=other_ds.layers[0]
    op=(op_name or "").lower()
    if op in ("intersection","clip"):
        new_feats=[]
        for f in layer.features:
            for g in other.features:
                if geometry_intersects_bbox(f.geometry, g.geometry): new_feats.append(f); break
        layer.features=new_feats
    elif op in ("difference","erase"):
        layer.features=[f for f in layer.features if not any(geometry_intersects_bbox(f.geometry,g.geometry) for g in other.features)]
    elif op in ("union","merge"):
        layer.features=layer.features+other.features
    elif op in ("symmetric-difference","symdifference"):
        a=[f for f in layer.features if not any(geometry_intersects_bbox(f.geometry,g.geometry) for g in other.features)]
        b=[f for f in other.features if not any(geometry_intersects_bbox(f.geometry,g.geometry) for g in layer.features)]
        layer.features=a+b
    return ds

def handle_vector_grid(path_key, invoked, parsed):
    # Grid interpolation to raster
    o=opts_dict(parsed, path_key)
    inp=o["input"][0] if isinstance(o["input"],list) else o["input"]
    ds=get_vector_input(path_key, invoked, inp)
    layers=ds.layers
    if o.get("input-layer"):
        names=o["input-layer"] if isinstance(o["input-layer"],list) else [o["input-layer"]]
        layers=[l for l in layers if l.name in names]
    layer=layers[0] if layers else Layer("layer")
    points=[]
    zfield=o.get("zfield")
    for f in layer.features:
        if f.geometry and f.geometry.get("type")=="Point":
            z=None
            if zfield: z=f.properties.get(zfield)
            elif layer.fields: 
                # first numeric field
                for fld in layer.fields:
                    if fld.type in ("Integer","Integer64","Real"): z=f.properties.get(fld.name); break
            if z is None: z=0
            points.append((float(f.geometry["coordinates"][0]), float(f.geometry["coordinates"][1]), float(z)*(float(o.get("zmultiply") or 1)) + float(o.get("zoffset") or 0)))
    # Extent
    extent=o.get("extent")
    if extent: xmin,ymin,xmax,ymax=[float(x) for x in extent]
    else:
        xs=[p[0] for p in points]; ys=[p[1] for p in points]; xmin=min(xs); ymin=min(ys); xmax=max(xs); ymax=max(ys)
    # size/resolution
    width=height=10
    if o.get("size"):
        sz=o["size"]; width=int(sz[0]); height=int(sz[1])
    elif o.get("resolution"):
        res=o["resolution"]; rx,ry=float(res[0]),float(res[1]); width=int(round((xmax-xmin)/rx)); height=int(round((ymax-ymin)/ry))
    method=path_key.split()[-1]
    radius=o.get("radius") or o.get("radius1")
    nodata_val=parse_nodata_value(o["nodata"]) if o.get("nodata") else None
    data=[]
    gt=(xmin,(xmax-xmin)/width,0,ymax,0,-(ymax-ymin)/height)
    for y in range(height):
        cy=ymax-(y+0.5)*(ymax-ymin)/height
        for x in range(width):
            cx=xmin+(x+0.5)*(xmax-xmin)/width
            # search radius
            candidates=[]
            for (px,py,pz) in points:
                d=math.hypot(px-cx,py-cy); candidates.append((d,pz,px,py))
            candidates.sort(key=lambda t:t[0])
            if radius:
                r=float(radius[0] if isinstance(radius,list) else radius); candidates=[c for c in candidates if c[0]<=r]
            min_points=int(o.get("min-points") or 0)
            if len(candidates)<min_points or not candidates: data.append(nodata_val if nodata_val is not None else 0); continue
            if method=="nearest": val=candidates[0][1]
            elif method=="count": val=len(candidates)
            elif method=="average": val=sum(c[1] for c in candidates)/len(candidates)
            elif method in ("average-distance",): val=sum(c[0] for c in candidates)/len(candidates)
            elif method=="average-distance-points":
                if len(candidates)<2: val=0
                else:
                    # average distance between points in search - approximate pairwise
                    pts=[(c[2],c[3]) for c in candidates]; dists=[]
                    for i in range(len(pts)):
                        for j in range(i+1,len(pts)): dists.append(math.hypot(pts[i][0]-pts[j][0],pts[i][1]-pts[j][1]))
                    val=sum(dists)/len(dists) if dists else 0
            elif method=="maximum": val=max(c[1] for c in candidates)
            elif method=="minimum": val=min(c[1] for c in candidates)
            elif method=="range": val=max(c[1] for c in candidates)-min(c[1] for c in candidates)
            elif method in ("invdist","invdistnn"):
                power=float(o.get("power") or 2.0); smoothing=float(o.get("smoothing") or 0)
                max_points=int(o.get("max-points") or 0)
                if max_points: candidates=candidates[:max_points]
                if candidates[0][0]==0: val=candidates[0][1]
                else:
                    wsum=0; vsum=0
                    for d,z,_,_ in candidates:
                        w=1/((d**power)+smoothing); wsum+=w; vsum+=w*z
                    val=vsum/wsum if wsum else 0
            elif method=="linear":
                # barycentric/plane fit - use nearest 3 plane
                if len(candidates)>=3:
                    # fit plane z = a x + b y + c using least squares for candidates up to ... use all
                    # Solve using normal equations 3x3 via simple Gaussian
                    pts=[(c[2],c[3],c[1]) for c in candidates]
                    # Use numpy-free linear algebra
                    ATA=[[0]*3 for _ in range(3)]; ATb=[0]*3
                    for (px,py,pz) in pts:
                        row=[px,py,1]
                        for i in range(3):
                            for j in range(3): ATA[i][j]+=row[i]*row[j]
                            ATb[i]+=row[i]*pz
                    try:
