def mdim_array_values(array_el, group_el, root, base_dir, display_base):
    # Determine dimensions and sizes
    dims=[]; sizes=[]
    # collect dimension definitions from group and ancestors? Only current group
    dim_defs={}
    for d in group_el.findall("Dimension"):
        dim_defs[d.get("name")]=int(d.get("size"))
    for dr in array_el.findall("DimensionRef"):
        ref=dr.get("ref"); dims.append(ref); sizes.append(dim_defs.get(ref,0))
    total=1
    for s in sizes: total*=s
    values=[0]*total
    dtype_el=array_el.find("DataType"); dtype=dtype_el.text.strip() if dtype_el is not None and dtype_el.text else "Byte"
