    if cv is not None and cv.text:
        try:
            txt=cv.text.strip(); v=float(txt) if any(c in txt for c in ".eE") and dtype.startswith("Float") else int(float(txt)) if dtype not in ("Float32","Float64","Float16") else float(txt)
        except Exception: v=cv.text.strip()
        values=[v]*total
