    def idx_to_offsets(idx, sizes):
        offs=[]
        for i,s in enumerate(reversed(sizes)):
            offs.append(idx % s if s else 0); idx//=s if s else 1
        return list(reversed(offs))
    def offset_to_flat(offs, sizes):
        flat=0
        for o,s in zip(offs,sizes): flat=flat*s+o
        return flat
    for src in array_el.findall("Source"):
        fn_el=src.find("SourceFilename")
        if fn_el is None: continue
        src_name=fn_el.text or ""
        rel=fn_el.get("relativeToVRT")=="1" or fn_el.get("relativetoVRT")=="1"
        src_path=os.path.join(base_dir, src_name) if rel and base_dir else src_name
        sb_el=src.find("SourceBand"); sb=int(sb_el.text) if sb_el is not None and sb_el.text else 1
        try: src_raster=open_raster(src_path)
