        src_off=[0]*len(sizes); src_cnt=sizes[:]; src_step=[1]*len(sizes)
        if slab is not None:
            if slab.get("offset"): src_off=[int(float(x)) for x in slab.get("offset").split(",")]
            if slab.get("count"): src_cnt=[int(float(x)) for x in slab.get("count").split(",")]
            if slab.get("step"): src_step=[int(float(x)) for x in slab.get("step").split(",")]
        dest_off=[0]*len(sizes)
        if dest is not None and dest.get("offset"): dest_off=[int(float(x)) for x in dest.get("offset").split(",")]
        # Iterate destination positions in slab
        # Generate ranges
        import itertools
        ranges=[range(c) for c in src_cnt]
        for prod in itertools.product(*ranges):
            dest_pos=[dest_off[i]+prod[i] for i in range(len(sizes))]
            if any(dest_pos[i]<0 or dest_pos[i]>=sizes[i] for i in range(len(sizes))): continue
